1	package clinical
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“返回结果隔离”约定补回归保障：调用方从 CreateExchange、幂等重试、
10	// GetExchange、ListExchanges、FetchPackage 拿到的交换、包内容与回执只是本次
11	// 操作的结果视图。调用方在本地修改手中的结果，既不能改写库内正式保存的交换
12	// （固化包、摘要、状态、回执），也不能波及另一份已经取得的结果；纯本地修改
13	// 不产生业务变更，也不新增审计事件。
14	
15	// ---- 测试自用的独立深拷贝与篡改工具 ----
16	//
17	// 刻意不调用生产代码的 cloneExchangeValue/clonePackage：预期基线由测试自行
18	// 深拷贝，这样即便生产拷贝退化为浅拷贝，基线仍保持创建时内容，隔离断言才能
19	// 真正抓住泄漏。
20	
21	// snapshotExchange 独立深拷贝一份交换作为预期基线（在篡改手中结果之前调用）。
22	func snapshotExchange(x Exchange) Exchange {
23		cp := x
24		recs := make([]PackagedRecord, len(x.Package.Records))
25		copy(recs, x.Package.Records)
26		cp.Package.Records = recs
27		if x.Receipt != nil {
28			r := *x.Receipt
29			cp.Receipt = &r
30		}
31		return cp
32	}
33	
34	// snapshotDelivery 独立深拷贝一份取包视图作为预期基线。
35	func snapshotDelivery(d PackageDelivery) PackageDelivery {
36		cp := d
37		recs := make([]PackagedRecord, len(d.Package.Records))
38		copy(recs, d.Package.Records)
39		cp.Package.Records = recs
40		return cp
41	}
42	
43	func recordsByID(recs []PackagedRecord) map[ID]PackagedRecord {
44		m := make(map[ID]PackagedRecord, len(recs))
45		for _, r := range recs {
46			m[r.RecordID] = r
47		}
48		return m
49	}
50	
51	// tamperExchangeResult 在调用方手中的交换上做尽可能广泛的本地修改：
52	// 状态、摘要、包头、首条记录的全部字段（内容/记录标识/版本标识/版本号等）、
53	// 记录集合（丢掉一条）以及回执（凭空伪造或覆盖既有回执）。
54	func tamperExchangeResult(x *Exchange) {
55		x.Status = ExchangeAccepted
56		x.Digest = "digest-tampered-by-caller"
57		x.Package.PatientID = "pat_tampered"
58		x.Package.ReceiverID = "rcv_tampered"
59		if len(x.Package.Records) > 0 {
60			x.Package.Records[0].EncounterID = "enc_tampered"
61			x.Package.Records[0].Category = Order
62			x.Package.Records[0].RecordID = "rec_tampered"
63			x.Package.Records[0].VersionID = "ver_tampered"
64			x.Package.Records[0].Version = 999
65			x.Package.Records[0].EffectiveAt = time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC)
66			x.Package.Records[0].Content = "调用方本地篡改的内容"
67		}
68		if len(x.Package.Records) > 1 {
69			// 调用方改动手中的记录集合（丢掉一条）。
70			x.Package.Records = x.Package.Records[:1]
71		}
72		x.Receipt = &Receipt{
73			Outcome:      ReceiptAccepted,
74			Reason:       "调用方在手中伪造的回执",
75			RegisteredAt: time.Date(2001, 2, 3, 4, 5, 6, 0, time.UTC),
76		}
77	}
78	
79	// tamperDeliveryResult 在接收方手中的取包视图上做同样广泛的本地修改。
80	func tamperDeliveryResult(d *PackageDelivery) {
81		d.ExchangeID = "exch_tampered"
82		d.Status = ExchangeAccepted
83		d.Digest = "digest-tampered-by-receiver"
84		d.CreatedAt = time.Date(2002, 3, 4, 5, 6, 7, 0, time.UTC)
85		d.Package.PatientID = "pat_tampered"
86		d.Package.ReceiverID = "rcv_tampered"
87		if len(d.Package.Records) > 0 {
88			d.Package.Records[0].EncounterID = "enc_tampered"
89			d.Package.Records[0].Category = Order
90			d.Package.Records[0].RecordID = "rec_tampered"
91			d.Package.Records[0].VersionID = "ver_tampered"
92			d.Package.Records[0].Version = 999
93			d.Package.Records[0].EffectiveAt = time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC)
94			d.Package.Records[0].Content = "接收方本地篡改的内容"
95		}
96		if len(d.Package.Records) > 1 {
97			d.Package.Records = d.Package.Records[:1]
98		}
99	}
100	
101	func assertExchangeMatches(t *testing.T, got, want Exchange, label string) {
102		t.Helper()
103		if got.ID != want.ID || got.Status != want.Status || got.Digest != want.Digest ||
104			got.PatientID != want.PatientID || got.ReceiverID != want.ReceiverID ||
105			got.AuthorizationID != want.AuthorizationID || got.RequestID != want.RequestID ||
106			got.CreatorID != want.CreatorID || !got.CreatedAt.Equal(want.CreatedAt) {
107			t.Fatalf("%s: exchange header changed:\n got=%+v\nwant=%+v", label, got, want)
108		}
109		if got.Package.PatientID != want.Package.PatientID || got.Package.ReceiverID != want.Package.ReceiverID {
110			t.Fatalf("%s: package header changed:\n got=%+v\nwant=%+v", label, got.Package, want.Package)
111		}
112		if len(got.Package.Records) != len(want.Package.Records) {
113			t.Fatalf("%s: record set changed: got %d records %+v, want %d records %+v",
114				label, len(got.Package.Records), got.Package.Records, len(want.Package.Records), want.Package.Records)
115		}
116		gm := recordsByID(got.Package.Records)
117		wm := recordsByID(want.Package.Records)
118		if len(gm) != len(wm) {
119			t.Fatalf("%s: duplicate record ids after mutation: %+v", label, got.Package.Records)
120		}
121		for rid, wr := range wm {
122			gr, ok := gm[rid]
123			if !ok {
124				t.Fatalf("%s: record %q missing from package: %+v", label, rid, got.Package.Records)
125			}
126			if gr != wr {
127				t.Fatalf("%s: record %q changed:\n got=%+v\nwant=%+v", label, rid, gr, wr)
128			}
129		}
130		if (got.Receipt == nil) != (want.Receipt == nil) {
131			t.Fatalf("%s: receipt presence changed: got present=%v, want present=%v",
132				label, got.Receipt != nil, want.Receipt != nil)
133		}
134		if want.Receipt != nil {
135			if got.Receipt.Outcome != want.Receipt.Outcome || got.Receipt.Reason != want.Receipt.Reason ||
136				!got.Receipt.RegisteredAt.Equal(want.Receipt.RegisteredAt) {
137				t.Fatalf("%s: receipt changed:\n got=%+v\nwant=%+v", label, *got.Receipt, *want.Receipt)
138			}
139		}
140	}
141	
142	func assertDeliveryMatches(t *testing.T, got, want PackageDelivery, label string) {
143		t.Helper()
144		if got.ExchangeID != want.ExchangeID || got.Status != want.Status ||
145			got.Digest != want.Digest || !got.CreatedAt.Equal(want.CreatedAt) {
146			t.Fatalf("%s: delivery header changed:\n got=%+v\nwant=%+v", label, got, want)
147		}
148		if got.Package.PatientID != want.Package.PatientID || got.Package.ReceiverID != want.Package.ReceiverID {
149			t.Fatalf("%s: delivery package header changed:\n got=%+v\nwant=%+v", label, got.Package, want.Package)
