292		conf2, err := s2.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重试成功的拒绝原因")
293		if err != nil {
294			t.Fatalf("idempotent resubmit: %v", err)
295		}
296		if conf2.ExchangeID != conf.ExchangeID || conf2.Status != conf.Status ||
297			conf2.Outcome != conf.Outcome || !conf2.RegisteredAt.Equal(conf.RegisteredAt) {
298			t.Fatalf("idempotent resubmit returned %+v, want original confirmation %+v", conf2, conf)
299		}
300		if n := len(mustAudit(t, s2, p.ID)); n != len(audit) {
301			t.Fatalf("idempotent resubmit added audit events: %d, want %d", n, len(audit))
302		}
303	
304		// 关闭后从同一数据位置重新打开：已拒绝状态、正式原因与登记时间完整
305		// 可见，失败尝试不作为另一份回执或事件出现。
306		if err := s2.Close(); err != nil {
307			t.Fatal(err)
308		}
309		s3 := open()
310		t.Cleanup(func() { _ = s3.Close() })
311	
312		got, err = s3.GetExchange(doc, p.ID, x.ID)
313		if err != nil {
314			t.Fatalf("get exchange after reopen: %v", err)
315		}
316		assertExchangeMatches(t, got, want, "exchange after reopen")
317	
318		audit3 := mustAudit(t, s3, p.ID)
319		if !reflect.DeepEqual(audit3, audit) {
320			t.Fatalf("audit after reopen:\nbefore: %+v\nafter:  %+v", audit, audit3)
321		}
322		var receiptEvents []AuditEvent
323		for _, ev := range audit3 {
324			if ev.Action == ActionReceipted {
325				receiptEvents = append(receiptEvents, ev)
326			}
327		}
328		if len(receiptEvents) != 1 || receiptEvents[0].ObjectID != x.ID ||
329			receiptEvents[0].ActorID != rcv.ID || !receiptEvents[0].OccurredAt.Equal(succeededAt) {
330			t.Fatalf("receipt events after reopen = %+v, want exactly one for %q at %v",
331				receiptEvents, x.ID, succeededAt)
332		}
333	}
