12	// TestReceiptResubmitConfirmedWithoutSave 为“交换回执的重复确认”补回归保障：
13	// 接收方已通过 SubmitReceipt 成功登记回执后，本地保存条件暂时不可用期间再次
14	// 提交同一份回执，必须仍能拿到首次成功登记时的原确认——重复确认只读取既有
15	// 结果，不能再次依赖写盘成功。
16	//
17	// 覆盖约定：
18	//   - 接受回执不保存原因：首次登记或重交时附带的原因文字都不会成为正式原因，
19	//     重交时文字不同也仍确认同一个接受结果；登记时间保持首次登记时刻，不被
20	//     改成重交时刻。
21	//   - 拒绝回执以“原拒绝结果 + 原原因”共同确认：原原因中的非空白文字及首尾
22	//     空格原样保留；原样重交（含空格）得到原确认；去掉首尾空格或换成另一段
23	//     非空白原因都返回 ErrConflict，不能覆盖已保存原因或登记时间。
24	//   - 接受改成带非空白原因的拒绝、拒绝改成接受，均明确冲突。
25	//   - 上述冲突在无法保存期间仍按业务规则返回，不能被保存错误替代；其他参数
26	//     合法但摘要不符，也不能因为交换已有回执而得到成功确认。
27	//   - 重复确认不改变内部视图中的正式回执、原包内容与摘要，不新增第二条回执
28	//     登记审计事件，既有审计事件保持原内容与顺序。
29	//   - 首次登记与重复确认的边界：另一份仍在等待回执的交换，即使接收方、摘要
30	//     与回执内容都合法，在同样无法保存的条件下首次登记仍返回实际保存错误，
31	//     内部继续看到待回执且无正式回执，不新增回执审计。
32	func TestReceiptResubmitConfirmedWithoutSave(t *testing.T) {
33		dir := t.TempDir()
34		clk := &fakeClock{t: time.Date(2026, 6, 2, 9, 0, 0, 0, time.UTC)}
35		open := func() *Store {
36			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
37			if err != nil {
38				t.Fatalf("open: %v", err)
39			}
40			return s
41		}
42	
43		s := open()
44		p, err := s.RegisterPatient(doc, "回执重复确认患者")
45		if err != nil {
46			t.Fatal(err)
47		}
48		e, err := s.AddEncounter(doc, p.ID, time.Time{})
49		if err != nil {
50			t.Fatal(err)
51		}
52		rd, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断v1内容")
53		if err != nil {
54			t.Fatal(err)
55		}
56		if _, err := s.ActivateRecord(doc, rd.ID); err != nil {
57			t.Fatal(err)
58		}
59		grant, err := s.Grant(doc, p.ID, rcv.ID,
60			[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
61			clk.t.Add(-time.Minute), clk.t.Add(72*time.Hour))
62		if err != nil {
63			t.Fatal(err)
64		}
65	
66		// 三份起点交换：一份接受、一份拒绝（均已成功登记），另一份仍待回执，
67		// 用于守住“首次登记仍须落盘”的边界。
68		newExchange := func(req string) Exchange {
69			x, err := s.CreateExchange(doc, p.ID, rcv.ID, grant.ID, []ID{rd.ID}, req)
70			if err != nil {
71				t.Fatalf("create exchange %q: %v", req, err)
72			}
73			return x
74		}
75		xAcc := newExchange("req-accepted")
76		xRej := newExchange("req-rejected")
77		xPending := newExchange("req-pending")
78	
79		// 首次登记接受回执：附带的原因文字必须被丢弃，不成为正式原因。
80		clk.t = clk.t.Add(time.Hour)
81		acceptedAt := clk.t
82		confAcc, err := s.SubmitReceipt(rcv, xAcc.ID, xAcc.Digest, ReceiptAccepted, "首次登记时随手附带的接受文字")
83		if err != nil {
84			t.Fatalf("first accepted receipt: %v", err)
85		}
86		if confAcc.ExchangeID != xAcc.ID || confAcc.Status != ExchangeAccepted ||
87			confAcc.Outcome != ReceiptAccepted || !confAcc.RegisteredAt.Equal(acceptedAt) {
88			t.Fatalf("unexpected first accepted confirmation: %+v", confAcc)
89		}
90	
91		// 首次登记拒绝回执：原因带非空白文字与首尾空格，必须原样保存。
92		clk.t = clk.t.Add(time.Hour)
93		rejectedAt := clk.t
94		rejectionReason := "\t 保留首尾空格的拒绝原因 \n"
95		confRej, err := s.SubmitReceipt(rcv, xRej.ID, xRej.Digest, ReceiptRejected, rejectionReason)
96		if err != nil {
97			t.Fatalf("first rejected receipt: %v", err)
98		}
99		if confRej.ExchangeID != xRej.ID || confRej.Status != ExchangeRejected ||
100			confRej.Outcome != ReceiptRejected || !confRej.RegisteredAt.Equal(rejectedAt) {
101			t.Fatalf("unexpected first rejected confirmation: %+v", confRej)
102		}
103	
104		// 保存条件不可用之前的正式基线：内部视图、审计与取包视图。
105		accBefore := snapshotExchange(mustGetExchange(t, s, p.ID, xAcc.ID))
106		rejBefore := snapshotExchange(mustGetExchange(t, s, p.ID, xRej.ID))
107		pendingBefore := snapshotExchange(mustGetExchange(t, s, p.ID, xPending.ID))
108		if accBefore.Receipt == nil || accBefore.Receipt.Outcome != ReceiptAccepted || accBefore.Receipt.Reason != "" {
109			t.Fatalf("accepted receipt must store no reason, got %+v", accBefore.Receipt)
110		}
111		if rejBefore.Receipt == nil || rejBefore.Receipt.Reason != rejectionReason {
112			t.Fatalf("rejected reason must be preserved verbatim, got %+v", rejBefore.Receipt)
113		}
114		if pendingBefore.Status != ExchangePending || pendingBefore.Receipt != nil {
115			t.Fatalf("pending baseline exchange must have no receipt: %+v", pendingBefore)
116		}
117		auditBefore, err := s.AuditEvents(doc, p.ID)
118		if err != nil {
119			t.Fatal(err)
120		}
121	
122		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败。
123		dataPath := filepath.Join(dir, dataName)
124		backupPath := dataPath + ".saved"
125		if err := os.Rename(dataPath, backupPath); err != nil {
126			t.Fatalf("backup data file: %v", err)
127		}
128		if err := os.Mkdir(dataPath, 0o755); err != nil {
129			t.Fatalf("block data path: %v", err)
130		}
131		restoreSave := func() {
132			t.Helper()
133			if err := os.Remove(dataPath); err != nil {
134				t.Fatalf("unblock data path: %v", err)
135			}
136			if err := os.Rename(backupPath, dataPath); err != nil {
137				t.Fatalf("restore data file: %v", err)
138			}
139		}
140	
141		// 重交时刻明确晚于两次首次登记：原确认的登记时间绝不能被改成这个时刻。
142		clk.t = clk.t.Add(2 * time.Hour)
143		resubmitAt := clk.t
144		if !resubmitAt.After(acceptedAt) || !resubmitAt.After(rejectedAt) {
145			t.Fatal("test clock must place resubmissions after first registrations")
146		}
147	
148		assertSameConfirmation := func(label string, got, want ReceiptConfirmation) {
149			t.Helper()
150			if got.ExchangeID != want.ExchangeID || got.Status != want.Status ||
151				got.Outcome != want.Outcome || !got.RegisteredAt.Equal(want.RegisteredAt) {
152				t.Fatalf("%s: confirmation changed:\n got=%+v\nwant=%+v (resubmit time %v must not be used)",
153					label, got, want, resubmitAt)
154			}
155		}
156	
157		// 1) 接受回执重交：换一段完全不同的原因文字，仍确认同一个接受结果，
158		//    不需要落盘即可在保存失败期间成功。
159		gotAcc, err := s.SubmitReceipt(rcv, xAcc.ID, xAcc.Digest, ReceiptAccepted, "重交时另一段完全不同的接受文字")
160		if err != nil {
