162		}
163		assertSameConfirmation("accepted resubmit", gotAcc, confAcc)
164	
165		// 2) 拒绝回执原样重交（含首尾空白）：得到首次登记的原确认。
166		gotRej, err := s.SubmitReceipt(rcv, xRej.ID, xRej.Digest, ReceiptRejected, rejectionReason)
167		if err != nil {
168			t.Fatalf("identical rejected resubmit during save failure: %v", err)
169		}
170		assertSameConfirmation("rejected resubmit", gotRej, confRej)
171	
172		// 3) 拒绝回执只去掉首尾空格：原因并非原样，必须冲突，空格不能被归一化。
173		if _, err := s.SubmitReceipt(rcv, xRej.ID, xRej.Digest, ReceiptRejected, "保留首尾空格的拒绝原因"); !errors.Is(err, ErrConflict) {
174			t.Fatalf("trimmed-reason resubmit err = %v, want ErrConflict", err)
175		}
176	
177		// 4) 拒绝回执改成另一段非空白原因：ErrConflict，不允许覆盖。
178		if _, err := s.SubmitReceipt(rcv, xRej.ID, xRej.Digest, ReceiptRejected, "试图覆盖的另一段拒绝原因"); !errors.Is(err, ErrConflict) {
179			t.Fatalf("different-reason resubmit err = %v, want ErrConflict", err)
180		}
181	
182		// 5) 已保存的接受改成带非空白原因的拒绝：明确冲突。
183		if _, err := s.SubmitReceipt(rcv, xAcc.ID, xAcc.Digest, ReceiptRejected, "想把接受翻成拒绝"); !errors.Is(err, ErrConflict) {
184			t.Fatalf("accepted->rejected err = %v, want ErrConflict", err)
185		}
186	
187		// 6) 已保存的拒绝改成接受：明确冲突。
188		if _, err := s.SubmitReceipt(rcv, xRej.ID, xRej.Digest, ReceiptAccepted, ""); !errors.Is(err, ErrConflict) {
189			t.Fatalf("rejected->accepted err = %v, want ErrConflict", err)
190		}
191	
192		// 7) 其他参数合法但摘要不符：不能因为交换已有回执就成功确认，也不能
193		//    返回保存错误——摘要核对先于重复确认，返回 ErrConflict。
194		if _, err := s.SubmitReceipt(rcv, xAcc.ID, "digest-does-not-match", ReceiptAccepted, ""); !errors.Is(err, ErrConflict) {
195			t.Fatalf("wrong digest on receipted exchange err = %v, want ErrConflict", err)
196		}
197		if _, err := s.SubmitReceipt(rcv, xRej.ID, "digest-does-not-match", ReceiptRejected, rejectionReason); !errors.Is(err, ErrConflict) {
198			t.Fatalf("wrong digest on rejected exchange err = %v, want ErrConflict", err)
199		}
200	
201		// 8) 首次登记边界：仍在等待回执的交换，接收方、摘要与回执内容均合法，
202		//    但保存失败——必须返回实际保存错误，而不是业务错误。
203		if _, err := s.SubmitReceipt(rcv, xPending.ID, xPending.Digest, ReceiptAccepted, ""); err == nil {
204			t.Fatal("first receipt registration during save failure must fail")
205		} else if errors.Is(err, ErrConflict) || errors.Is(err, ErrInvalidArgument) ||
206			errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) ||
207			errors.Is(err, ErrNotFound) {
208			t.Fatalf("save failure surfaced as a business error: %v", err)
209		}
210		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
211			t.Fatalf("failed save left a temp file: %v", statErr)
212		}
213	
214		// 保存失败期间内部视图仍可查：正式回执、原包内容与摘要均保持首次登记
215		// 后状态，重交与冲突尝试没有留下任何变化。
216		assertExchangeMatches(t, mustGetExchange(t, s, p.ID, xAcc.ID), accBefore, "accepted exchange during outage")
217		assertExchangeMatches(t, mustGetExchange(t, s, p.ID, xRej.ID), rejBefore, "rejected exchange during outage")
218		assertExchangeMatches(t, mustGetExchange(t, s, p.ID, xPending.ID), pendingBefore, "pending exchange during outage")
219	
220		// 审计：重复确认不新增第二条回执事件，冲突尝试与失败的首次登记也不新增，
221		// 既有事件保持原内容与顺序。
222		auditDuring, err := s.AuditEvents(doc, p.ID)
223		if err != nil {
224			t.Fatal(err)
225		}
226		if !reflect.DeepEqual(auditDuring, auditBefore) {
227			t.Fatalf("audit changed during outage:\nbefore: %+v\nafter:  %+v", auditBefore, auditDuring)
228		}
229	
230		// 取包视图同样维持原状态与原摘要。
231		dAcc, err := s.FetchPackage(rcv, xAcc.ID)
232		if err != nil {
233			t.Fatal(err)
234		}
235		if dAcc.Status != ExchangeAccepted || dAcc.Digest != xAcc.Digest {
236			t.Fatalf("accepted delivery changed during outage: %+v", dAcc)
237		}
238		dRej, err := s.FetchPackage(rcv, xRej.ID)
239		if err != nil {
240			t.Fatal(err)
241		}
242		if dRej.Status != ExchangeRejected || dRej.Digest != xRej.Digest {
243			t.Fatalf("rejected delivery changed during outage: %+v", dRej)
244		}
245	
246		// 恢复保存条件：内存中的正式状态与中断前一致（中断期间本就无落盘）。
247		restoreSave()
248	
249		gotAcc2 := mustGetExchange(t, s, p.ID, xAcc.ID)
250		gotRej2 := mustGetExchange(t, s, p.ID, xRej.ID)
251		gotPending2 := mustGetExchange(t, s, p.ID, xPending.ID)
252		assertExchangeMatches(t, gotAcc2, accBefore, "accepted exchange after recovery")
253		assertExchangeMatches(t, gotRej2, rejBefore, "rejected exchange after recovery")
254		assertExchangeMatches(t, gotPending2, pendingBefore, "pending exchange after recovery")
255		if gotAcc2.Receipt.Reason != "" || !gotAcc2.Receipt.RegisteredAt.Equal(acceptedAt) {
256			t.Fatalf("accepted receipt altered by resubmits: %+v", gotAcc2.Receipt)
257		}
258		if gotRej2.Receipt.Reason != rejectionReason || !gotRej2.Receipt.RegisteredAt.Equal(rejectedAt) {
259			t.Fatalf("rejected receipt altered by conflicting attempts: %+v", gotRej2.Receipt)
260		}
261		if gotPending2.Status != ExchangePending || gotPending2.Receipt != nil {
262			t.Fatalf("failed first registration left a receipt: %+v", gotPending2)
263		}
264		// 包摘要仍可由原包内容重算，重复确认没有触发重新打包。
265		for _, g := range []Exchange{gotAcc2, gotRej2, gotPending2} {
266			if recomputed := packageDigest(g.Package); recomputed != g.Digest {
267				t.Fatalf("package regenerated for exchange %q: digest %q, recomputed %q", g.ID, g.Digest, recomputed)
268			}
269		}
270	
271		auditAfter, err := s.AuditEvents(doc, p.ID)
272		if err != nil {
273			t.Fatal(err)
274		}
275		if !reflect.DeepEqual(auditAfter, auditBefore) {
276			t.Fatalf("audit changed after recovery:\nbefore: %+v\nafter:  %+v", auditBefore, auditAfter)
277		}
278		// 每份已登记交换恰好一条回执事件，待回执交换没有任何回执事件。
279		receiptEvents := map[ID][]AuditEvent{}
280		for _, ev := range auditAfter {
281			if ev.Action == ActionReceipted {
282				receiptEvents[ev.ObjectID] = append(receiptEvents[ev.ObjectID], ev)
283			}
284		}
285		if len(receiptEvents[xAcc.ID]) != 1 || receiptEvents[xAcc.ID][0].OccurredAt != acceptedAt ||
286			receiptEvents[xAcc.ID][0].ActorID != rcv.ID {
287			t.Fatalf("accepted exchange receipt events = %+v, want one at %v", receiptEvents[xAcc.ID], acceptedAt)
288		}
289		if len(receiptEvents[xRej.ID]) != 1 || receiptEvents[xRej.ID][0].OccurredAt != rejectedAt ||
290			receiptEvents[xRej.ID][0].ActorID != rcv.ID {
291			t.Fatalf("rejected exchange receipt events = %+v, want one at %v", receiptEvents[xRej.ID], rejectedAt)
292		}
293		if len(receiptEvents[xPending.ID]) != 0 {
294			t.Fatalf("pending exchange must have no receipt events, got %+v", receiptEvents[xPending.ID])
295		}
296	
297		// 关闭后从同一数据位置重新打开：磁盘上的正式状态与上述全部断言一致，
298		// 中断期间的重复确认/冲突/失败首登都没有改变任何已保存内容。
299		if err := s.Close(); err != nil {
300			t.Fatal(err)
301		}
302		s2 := open()
303		t.Cleanup(func() { _ = s2.Close() })
304	
305		assertExchangeMatches(t, mustGetExchange(t, s2, p.ID, xAcc.ID), accBefore, "accepted exchange after reopen")
306		assertExchangeMatches(t, mustGetExchange(t, s2, p.ID, xRej.ID), rejBefore, "rejected exchange after reopen")
307		assertExchangeMatches(t, mustGetExchange(t, s2, p.ID, xPending.ID), pendingBefore, "pending exchange after reopen")
308		auditReopen, err := s2.AuditEvents(doc, p.ID)
309		if err != nil {
310			t.Fatal(err)
311		}
312		if !reflect.DeepEqual(auditReopen, auditBefore) {
313			t.Fatalf("audit changed after reopen:\nbefore: %+v\nafter:  %+v", auditBefore, auditReopen)
314		}
315	
316		// 恢复后首次登记此前待回执的交换：保存成功，只新增一条回执审计，
317		// 证明中断期间的失败尝试没有建立任何回执。
318		clk.t = clk.t.Add(time.Hour)
319		registeredAfterRecovery := clk.t
320		confPending, err := s2.SubmitReceipt(rcv, xPending.ID, xPending.Digest, ReceiptAccepted, "")
321		if err != nil {
322			t.Fatalf("first registration after recovery: %v", err)
323		}
324		if confPending.Status != ExchangeAccepted || !confPending.RegisteredAt.Equal(registeredAfterRecovery) {
325			t.Fatalf("unexpected confirmation after recovery: %+v", confPending)
326		}
327		auditFinal, err := s2.AuditEvents(doc, p.ID)
328		if err != nil {
329			t.Fatal(err)
330		}
331		if len(auditFinal) != len(auditBefore)+1 || !reflect.DeepEqual(auditFinal[:len(auditBefore)], auditBefore) {
332			t.Fatalf("audit after late first registration:\nbefore: %+v\nafter:  %+v", auditBefore, auditFinal)
333		}
334	}
335	
336	// mustGetExchange 取内部使用者视角下的交换，失败即终止测试。
337	func mustGetExchange(t *testing.T, s *Store, pid, xid ID) Exchange {
338		t.Helper()
339		x, err := s.GetExchange(doc, pid, xid)
340		if err != nil {
341			t.Fatalf("get exchange %q: %v", xid, err)
342		}
343		return x
344	}
